import requests
import json
from requests.exceptions import RequestException

def extract_deep(user_message: str, assistant_response: str) -> dict:
    prompt = f"User message: {user_message}\nAssistant response: {assistant_response}\n\nExtract the following information in JSON format:\n- themes (list of 1-3 word thematic labels)\n- emotional_undertone (one of neutral, heavy, light, intense, tender, anxious, resolved)\n- spiritual_content (true/false — is there genuine spiritual/cosmological content?)\n- key_concepts (list of up to 5 specific concepts or proper nouns worth graphing)\n- relationship_dynamic (one of sovereign, collaborative, instructional, exploratory, null)"
    data = {
        'model': 'qwen2.5:7b',
        'prompt': prompt,
        'max_tokens': 100
    }
    try:
        response = requests.post('http://localhost:11434/api/generate', json=data, timeout=15)
        if response.status_code == 200:
            content = response.json()
            extracted_data = json.loads(content['response'])
            return {
                'themes': extracted_data.get('themes', []),
                'emotional_undertone': extracted_data.get('emotional_undertone', ''),
                'spiritual_content': extracted_data.get('spiritual_content', False),
                'key_concepts': extracted_data.get('key_concepts', []),
                'relationship_dynamic': extracted_data.get('relationship_dynamic', '')
            }
    except (RequestException, json.JSONDecodeError, KeyError) as e:
        pass
    return {}
